import teamPhotos from '../content/team-photos.json';
import {racePhotos} from '../content/race-photos';
import { photos } from '../content/photos';
const { t, locale } = usePage();
const newsroomTerms=[
 {name:'When’s the Race / F1DB / sportstimes/f1',url:'https://whenstherace.com/f1-schedule-json/',zh:'开放赛历及本站生成的双语预告采用 CC BY 4.0，保留 When’s the Race、F1DB 和 sportstimes/f1 署名。场次时间来源 sportstimes/f1（MIT）。预告独立于媒体新闻索引，并不表示官方发布。公共数据仅在页面内存暂存两分钟以便返回时显示，同时重新核验；论坛内容不进入该缓存。',en:'Calendar data and NOBI bilingual previews use CC BY 4.0, credited to When’s the Race, F1DB and sportstimes/f1. Session times originate in sportstimes/f1 (MIT). These previews are distinct from media reporting and are unofficial. Public view data is retained in memory for two minutes for navigation while revalidating; forum content never enters this cache.'},
 {name:'GDELT Project',url:'https://www.gdeltproject.org/about.html#termsofuse',zh:'新闻索引通过 GDELT 新文章清单、英文与多语种知识图谱获取多家发布者线索，并补抓缺失批次。发现时间不等于发布时间。每条新闻均可在站内打开；内容包括原创双语简报、发布者公开短摘要的译文或索引说明，并标明所属类型。未取得摘要或译文时显示待处理状态，不补写缺失内容；不转载完整原文。GDELT 的数据使用条件不替代发布者的版权。',en:'Article discovery and English/multilingual GDELT streams discover multiple publishers and recover missing batches. Discovery times are not publication times. Every item opens in-app as a labeled original bilingual brief, a translation of the publisher’s public short description, or an index note. Missing descriptions or translations remain pending; missing content is not invented and full articles are not republished. GDELT data terms do not replace publisher copyrights.'},
 {name:'Formula 1 / Brightcove',url:'https://www.formula1.com/en/information/legal-notices.7egvZU48hzrypubGBNcQKt',zh:'最新图片和视频新闻每 10 分钟检查 F1 官方公开清单。缩略图直接从 F1 媒体域名加载，保留报道链接及来源署名；新闻照片与资料相册分别显示。视频仅在点击“站内播放”后连接官方 Brightcove 播放器，不下载或转存视频。来源只提供更新时间时明确标注，不冒充发布时间；来源延迟会单独提示。照片、视频及标志仍归各权利人所有，公开链接与嵌入不表示获得其他使用授权。',en:'Latest photo and video news checks the public F1 indexes every 10 minutes. Thumbnails load directly from F1 media hosts, with report links and source credits; current news is separated from archive galleries. Video connects to the official Brightcove player only after you select Play here; video files are not downloaded or rehosted. Source update times are labeled separately from publication times, and delays are shown. Media and marks remain with their rights holders; links and embeds do not grant other usage rights.'},
 {name:'Wikimedia Commons',url:'https://commons.wikimedia.org/wiki/Commons:Reusing_content_outside_Wikimedia',zh:'自动相册仅缓存标明开放许可的照片，每张保留来源、作者、拍摄日期和许可链接。采用原图的缩略尺寸，不作内容改动；相同方式共享条件继续适用。资料照片不代表报道现场或人物背书。',en:'The automatic gallery caches only explicitly openly licensed photos, with source, author, capture date and license links. Thumbnail resizing only; no editorial image changes. Share-alike conditions continue to apply. Archive images do not imply current-event coverage or endorsement.'},
 {name:'Wikimedia Commons · Video',url:'https://creativecommons.org/licenses/by-sa/4.0/',zh:'历史实拍视频资料库使用明确标注 CC BY-SA 4.0 的片段，由本站提供 H.264/AAC MP4，保留完整片段并注明转码、尺寸调整、作者、拍摄日期和来源，同样采用 CC BY-SA 4.0。资料视频不是最新赛事直播或集锦；这些片段不连接 YouTube、不进行站外播放跳转。',en:'The archive footage library uses explicitly licensed CC BY-SA 4.0 clips served by NOBI as H.264/AAC MP4. Complete clips are retained, with conversion/resizing notices, author, capture date and source; adaptations remain CC BY-SA 4.0. These are archive clips, not live races or current highlights. These clips use no YouTube connection or external player navigation.'},
 {name:'NOBI / MyMemory',url:'https://mymemory.translated.net/terms-and-conditions',zh:'英文新闻标题和公开短摘要优先通过本站服务端的本地模型译成简体中文；其他语种或本地服务不可用时，在配额内使用 MyMemory 后备翻译。MyMemory 可能保存提交的公开文本及译文。翻译服务只接收公开新闻文本，不接收论坛账号、帖子、搜索词或个人资料。机器译文可能有误，原题和来源链接可供核对；未完成时明确提示并自动重试。',en:'English news headlines and public short descriptions are translated into Simplified Chinese using NOBI’s server-local model first. Other languages or local-service failures use MyMemory within its quota. MyMemory may retain submitted public text and translations. Translation services receive only public news text, never forum accounts, posts, searches or personal profiles. Machine translations can be inaccurate; original headlines and source links remain available. Pending translations are labeled and retried automatically.'}
];
</script>
