class="license-photo"><img :src="assetUrl(photo.src)" :alt="photo.title" loading="lazy"/><figcaption>{{photo.team}} · {{photo.captured}} · {{photo.author}} · <a :href="safeHref(photo.source)" :target="(safeHref(photo.source))?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">{{photo.title}}</a> · <a :href="safeHref(photo.licenseUrl)" :target="(safeHref(photo.licenseUrl))?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">{{photo.license}}</a><p>{{photo.modifications}}</p></figcaption></figure></section><section id="photos"><h2>{{ t('legal.photosTitle') }}</h2><p>{{ t('legal.photoPolicy') }}</p><figure v-for="photo in photos" :key="photo.src" class="license-photo"><img :src="assetUrl(photo.src)" :alt="locale === 'zh-CN' ? photo.altZh : photo.alt" loading="lazy"/><figcaption><p>{{ locale === 'zh-CN' ? photo.altZh : photo.alt }}</p><a :href="safeHref(photo.source)" :target="(safeHref(photo.source))?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">{{ photo.author }} · Wikimedia Commons ↗</a> · <a :href="safeHref(photo.licenseUrl)" :target="(safeHref(photo.licenseUrl))?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">{{ photo.license }} ↗</a><p>{{ t('legal.modifications') }}</p></figcaption></figure></section><section><h2>{{t('circuitMap.title')}}</h2><p>{{t('circuitMap.attribution')}}</p><p><a :href="safeHref('https://github.com/f1db/f1db')" :target="(safeHref('https://github.com/f1db/f1db'))?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">Jules Roy / F1DB ↗</a> · <a :href="safeHref(assetUrl('/media/circuits/LICENSE.txt'))" :target="(safeHref(assetUrl('/media/circuits/LICENSE.txt')))?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">CC BY 4.0 ↗</a></p></section><section><h2>{{t('stats.title')}}</h2><p>{{t(publicReference?'publicData.dataLicense':'insights.license')}}</p><p><a :href="safeHref(publicReference?'https://github.com/f1db/f1db':'https://openf1.org/docs/#drivers-championship-beta')" :target="(safeHref(publicReference?'https://github.com/f1db/f1db':'https://openf1.org/docs/#drivers-championship-beta'))?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">{{publicReference?'F1DB':'OpenF1'}} ↗</a> · <a :href="safeHref(publicReference?'https://creativecommons.org/licenses/by/4.0/':'https://creativecommons.org/licenses/by-nc-sa/4.0/')" :target="(safeHref(publicReference?'https://creativecommons.org/licenses/by/4.0/':'https://creativecommons.org/licenses/by-nc-sa/4.0/'))?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">{{publicReference?'CC BY 4.0':'CC BY-NC-SA 4.0'}} ↗</a></p></section><section><h2>{{ t('legal.references') }}</h2><ul><li><a href="https://www.bbc.co.uk/sport/articles/cqllxj2n4kyo" target="_blank" rel="noopener noreferrer">BBC Sport — RSS ↗</a></li><li><a href="https://www.bbc.co.uk/usingthebbc/terms-of-use/#15metadataandrssfeeds" target="_blank" rel="noopener noreferrer">BBC — RSS terms ↗</a></li><li><a href="https://www.formula1.com/en/information/legal-notices.7egvZU48hzrypubGBNcQKt" target="_blank" rel="noopener noreferrer">Formula1.com — Legal Notices ↗</a></li><li><a href="https://www.formula1.com/en/information/guidelines.4EOKE9RRqevL4niTK9kWyt" target="_blank" rel="noopener noreferrer">Formula 1 — Guidelines ↗</a></li><li><a href="https://www.miit.gov.cn/jgsj/zfs/fl/art/2022/art_515a4b20c12f430eab54bb4f56d89f56.html" target="_blank" rel="noopener noreferrer">中华人民共和国个人信息保护法 ↗</a></li><li><a href="https://www.miit.gov.cn/datainfo/fgk/gytxyxxhfg/xzfg/art/2020/art_44595811ff9a42b9b073386046905103.html" target="_blank" rel="noopener noreferrer">互联网信息服务管理办法 ↗</a></li></ul></section><RouterLink class="button" to="/settings">{{ t('settings.privacy') }} →</RouterLink></article></template>
